/**
 * Base64-encoded enemy sprite
 * A simple enemy character
 */
export const ENEMY_SPRITE_BASE64 = 'data:image/png;base64,';

/**
 * Base64-encoded power-up sprite
 * A simple power-up item
 */
export const POWERUP_SPRITE_BASE64 = 'data:image/png;base64,'; 